-- G7 本地 embedding 回落档来源标注(2026-10-31,goal-b42,对标 Trae ckg
-- `-local_embedding -embedding_storage_type=sqlite_vec` 命令行常量,T2 §8-G7)。
-- codebase_chunks.embedding_provider:本行向量来自哪条生成通道 ——
--   NULL       = 存量行(迁移前的历史数据,来源未标注,不回填不猜测);
--   'remote'   = 在线 provider(litellm 远端 embedding);
--   'local-hash' = 离线/远端不可用时的本地确定性回落(char-trigram 哈希投影,
--                维度与列一致但无神经语义精度 —— 必须可识别,不得冒充在线质量)。
-- nullable:该列只标注来源,不参与检索判序;检索质量退化由 hybrid 的 keyword 腿兜底。

ALTER TABLE "codebase_chunks" ADD COLUMN IF NOT EXISTS "embedding_provider" varchar(32);
